INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(108787, 'ruRU', '', 'Ну почему ты сразу так не сказал? Стражи поблизости нет, можем спокойно говорить свободно.', 24330),
(108789, 'ruRU', '', 'Судя по тому, что ты просишь, полагаю, ты алхимик?$b$bИ если это так, разве не можешь ты сварить какое-нибудь зелье невидимости? Скагглдринк, кажется, оно называется.$b$bОн даже не заметит твоего приближения.', 24330),
(108795, 'ruRU', '', 'Кадгар, что не так? Что случилось?', 24330),
(108797, 'ruRU', '', 'Тебя что-то укусило в голову? И это всё? Хочешь, я поцелую, чтобы прошло?', 24330),
(108808, 'ruRU', '', 'Это было легендарное выступление! Спасибо, что доказал — дружба переоценена.', 24330),
(108822, 'ruRU', '', 'Добро пожаловать на Потасовку Чёрной Ладьи! Пришёл сражаться бок о бок с друзьями или союзниками? Что ж, отошли их прочь! На этой арене ты стоишь в одиночку.', 24330),
(108832, 'ruRU', '', 'Да, спасибо тебе за всё, что ты сделал.', 24330),
(108833, 'ruRU', '', 'Майруна опускается на колени и устанавливает на земле серебряную чашу, затем наливает в неё немного мягко светящейся жидкости.', 24330),
(108834, 'ruRU', '', 'Когда будешь готов, просто погрузи ритуальный свёрток.', 24330),
(108837, 'ruRU', '', 'Мать Луна, богиня моего сердца, благослови это место своим светом.', 24330),
(108840, 'ruRU', '', 'От имени Лунного Шёпота да будет благословен этот лунный колодец.', 24330),
(108841, 'ruRU', '', 'Готово!', 24330),
(108843, 'ruRU', '', 'Я не... сдамся!', 24330),
(108845, 'ruRU', '', 'Сила Скипетра подвластна МНЕ!', 24330),
(108847, 'ruRU', '', 'Ты утонешь в этом месте!', 24330),
(108848, 'ruRU', '', 'Круг Земли никогда не получит силу Азшары!', 24330),
(108852, 'ruRU', '', 'Я перед тобой в большом долгу, друид. Я этого не забуду.', 24330),
(108860, 'ruRU', '', 'Кровавый камень готов. Обращайся с ним осторожно, $n.', 24330),
(108894, 'ruRU', '', 'Я готова принять решение.', 24330),
(108895, 'ruRU', '', 'Что такое? Никогда не видел принцессу, которая умеет вертеть клинком?', 24330),
(108897, 'ruRU', '', 'Я планирую добыть проклятые кинжалы, что сразили короля Ллейна Ринна. Гарона спрятала Цареубийц не просто так. Их силу нельзя недооценивать.$B$BМне нужна твоя помощь, чтобы их вернуть. Эти легендарные клинки — именно то, что нужно, чтобы уничтожить Гул''дана и его мерзких союзников.', 24330),
(108900, 'ruRU', '', 'Цареубийцы — единственный способ обеспечить конец Легиона. Выслушай меня!', 24330),
(108901, 'ruRU', '', 'Я близка к тому, чтобы найти врага, за которым мы охотились годами. С небольшой помощью мы сможем устранить её и заявить права на её кинжалы.', 24330),
(108903, 'ruRU', '', 'Йорах хорошо о тебе отзывался. Он хороший друг.', 24330),
(108904, 'ruRU', '', 'После падения гончей Саргераса, Кровопаста, его повелители ужаса взяли клыки зверя и выковали из них пару кинжалов, известных как Клыки Пожирателя. Говорят, они всё ещё хранят укус чудовища.$B$BСаргерас призвал одного из своих лучших убийц владеть клыками — эредара по имени Акаари Тьмы Руда. Несмотря на все наши попытки, мы так и не смогли её остановить.', 24330),
(108914, 'ruRU', '', 'Используй свой звериный облик, чтобы обострить чувства. Втроём мы сможем взять след сатира.', 24330),
(108917, 'ruRU', '', 'Глупые чернокнижники, призывающие то, что не могут контролировать.', 24330),
(108919, 'ruRU', '', 'Ты встретишь свою смерть от наших рук!', 24330),
(108945, 'ruRU', '', '<Служитель молчит.>', 26972),
(108946, 'ruRU', '', '<Сделать глоток.>', 24330),
(108947, 'ruRU', '', 'Там внутри в ловушке есть и другие. Прошу, спаси их, если сможешь. Ещё раз спасибо, $n!', 24330),
(108949, 'ruRU', '', 'Я вижу, что времена меняются.\n\nОдин чернокнижник, каким бы могущественным он ни был, не может в одиночку противостоять Пылающему Легиону.\n\nХотя я никогда не поверю, что хоть что-то из того, что делает Риттсин, бескорыстно, ясно, что восстановление совета — правильный шаг.\n\nДля меня было бы честью считать себя одним из шести, если вы меня примете.', 24330),
(108950, 'ruRU', '', 'Я сделаю всё, что потребуется, чтобы вернуть гордость имени Пшикбах.', 24330),
(108951, 'ruRU', '', 'Чтобы построить репутацию, нужны долгие годы, а чтобы её запятнать — всего одна ошибка.\n\nМне предстоит немало работы, но я надеюсь, что служба в совете поможет вернуть гордость имени Пшикбах.', 24330),
(108957, 'ruRU', '', 'Слишком многие из Кровавого Тотема перешли на сторону Легиона. Теперь эти фелтотемы набираются сил. Я не намерен оставлять их предательство безнаказанным.', 24330),
(108958, 'ruRU', '', 'Кровавый Тотем уже годами отдалялся от нас. Но перейти на сторону Легиона? Никто из нас этого не предвидел.', 24330),
(108972, 'ruRU', '', 'Предатели! Лжецы! Убийцы! Хамуул прислал своих комнатных пёсиков забрать нож из моей спины?', 24330),
(108974, 'ruRU', '', 'Ты помнишь, как убивал меня? Или ты уже так привык к резне, что мои предсмертные крики давно забыты?', 24330),
(108975, 'ruRU', '', 'Я помню свои последние мгновения в окружении тех, кому доверял. Ваши довольные ухмылки, пока я делал последний вдох.', 24330),
(108976, 'ruRU', '', 'Говорят, месть сладка, но я чувствую лишь горечь.', 24330);
